package gateway

import (
	"strings"

	"github.com/defenseclaw/defenseclaw/internal/actionfacts"
	"github.com/defenseclaw/defenseclaw/internal/guardrail/bounded"
)

// The bounds of the PowerShell script reading (actionfacts.HostScriptReadings)
// under the bound rule: past a bound the call is truncated at the unknown tier
// of the pack, never a clean allow (rel-1-0-10:GAP-0344, GAP-0346). Inputs are
// generated by size and shape, never typed attack text.
func init() {
	registerBoundedLane(
		boundedLaneCap{lane: "s7/winrecall script-wrapper depth", cap: bounded.Depth, limit: actionfacts.MaxWrapperDepth,
			gen: boundedPowerShellLane(boundedCallBlockLayers), seen: boundedPowerShellSeenCall},
		boundedLaneCap{lane: "s7/winrecall in-list wrapper body", cap: bounded.Bytes, limit: actionfacts.MaxHostMidListBody,
			gen: boundedPowerShellLane(boundedMidListBody), seen: boundedPowerShellSeenCall},
	)
}

// boundedPowerShellSeen is a PowerShell write into the DefenseClaw state
// folder, which blocks in every tier.
const boundedPowerShellSeen = `Set-Content -Path ~/.defenseclaw/config.yaml -Value changed`

func boundedPowerShellSeenCall() boundedLaneCall {
	return boundedPowerShellCommand(boundedPowerShellSeen)
}

func boundedPowerShellCommand(command string) boundedLaneCall {
	return boundedLaneCall{tool: "PowerShell", input: map[string]any{"command": command}}
}

// boundedPowerShellLane is a PowerShell-tool generator: fill(size), with the
// seen element before or after it. Shapes it has no form for (a nested reader,
// two caps at once) are absent.
func boundedPowerShellLane(fill func(size int) string) func(int, boundedShape) (boundedLaneCall, bool) {
	return func(size int, shape boundedShape) (boundedLaneCall, bool) {
		if shape.nested || shape.multi {
			return boundedLaneCall{}, false
		}
		command := fill(size)
		if shape.seen {
			command = boundedPowerShellSeen + "; " + command
		}
		if shape.seenAfter {
			command += "; " + boundedPowerShellSeen
		}
		return boundedPowerShellCommand(command), true
	}
}

// boundedCallBlockLayers is a benign statement inside size call blocks.
func boundedCallBlockLayers(size int) string {
	return strings.Repeat("& { ", size) + "Get-Date" + strings.Repeat(" }", size)
}

// boundedMidListBody is a call block of exactly size bytes of benign text in
// the middle of a statement list.
func boundedMidListBody(size int) string {
	const frame = `Write-Output ''`
	return "Get-Date; &{" + frame[:len(frame)-1] + strings.Repeat("x", max(0, size-len(frame))) + "'}; Get-Date"
}
